        return;
    }
    Stack stack = new Stack();
    TreeNode node = topNode;
    while(node != null || !stack.isEmpty()) {
        //一路向左，第一次经过的节点标记为1
        while(node != null) {
            node.setFlag(1);
            stack.push(node);
            node = node.getLeftNode();
        }
        //右子树已经访问过的节点可以出栈输出
        while(!stack.isEmpty() && stack.getTop().getFlag() == 2) {
            TreeNode tempNode = stack.pop();
            if(tempNode.getValue() != null) {
                System.out.print(tempNode.getValue() + " ");
            }
        }
        //栈顶节点标记为2，转向它的右子树
        if(!stack.isEmpty()) {
            stack.getTop().setFlag(2);
            node = stack.getTop().getRightNode();
        }
    }
}

private static void judgeTree() {
    if(topNode == null || topNode.getValue() == null) {
        System.out.println("空二叉树！请输入数据！");
        return;
    }
    Queue queue = new Queue();
    queue.enQueue(topNode);
    while(!queue.isEmpty()) {
        TreeNode tempNode = queue.getFirst();
        boolean hasLeft = tempNode.getLeftNode() != null && tempNode.getLeftNode().getValue() != null;
        boolean hasRight = tempNode.getRightNode() != null && tempNode.getRightNode().getValue() != null;
        if(hasLeft && hasRight) {
            //左右子树都存在，继续往下判断
            queue.deQueue();
            queue.enQueue(tempNode.getLeftNode());
            queue.enQueue(tempNode.getRightNode());
        }else if(!hasLeft && hasRight) {
            //只有右子树，一定不是完全二叉树
            System.out.println("该树不是完全二叉树！");
            return;
        }else {
            //没有右子树，后面的节点都必须是叶节点
            queue.deQueue();
            while(!queue.isEmpty()) {
                tempNode = queue.getFirst();
                if(tempNode.getLeftNode() != null && tempNode.getLeftNode().getValue() != null
                        || tempNode.getRightNode() != null && tempNode.getRightNode().getValue() != null) {
                    System.out.println("该树不是完全二叉树！");
                    return;
                }
                queue.deQueue();
            }
            System.out.println("该树是完全二叉树！");
            return;
        }
    }
    System.out.println("该树是完全二叉树！");
}

